import PublicKey from '../primitives/PublicKey.js'
import PrivateKey from '../primitives/PrivateKey.js'
import Signature from '../primitives/Signature.js'
import Random from '../primitives/Random.js'
import { toBase64, toArray, Reader, toHex } from '../primitives/utils.js'
import {
  copyMessageBytes,
  copyPrivateKey,
  copyPublicKey,
  MAX_SIGNED_MESSAGE_BYTES,
  MIN_SIGNED_MESSAGE_BYTES
} from './MessageValidation.js'

const VERSION = '42423301'

/**
 * Signs a message from one party to be verified by another, or for verification by anyone, using the BRC-77 message signing protocol.
 * @param message The message to sign
 * @param signer The private key of the message signer
 * @param [verifier] The public key of the person who can verify the message. If not provided, anyone will be able to verify the message signature.
 *
 * @returns The message signature.
 *
 * The verifier must be omitted deliberately for an anyone-verifiable signature;
 * malformed runtime values are rejected rather than widening the audience. The
 * signed message is limited to 16 MiB and must be a dense byte array.
 */
export const sign = (message: number[], signer: PrivateKey, verifier?: PublicKey): number[] => {
  const plaintext = copyMessageBytes(message, 'Message')
  const signerKey = copyPrivateKey(signer, 'Signer')
  const recipientAnyone = verifier === undefined
  let verifierKey: PublicKey
  if (recipientAnyone) {
    verifierKey = new PrivateKey(1).toPublicKey()
  } else {
    verifierKey = copyPublicKey(verifier, 'Verifier')
  }
  const keyID = Random(32)
  const keyIDBase64 = toBase64(keyID)
  const invoiceNumber = `2-message signing-${keyIDBase64}`
  const signingKey = signerKey.deriveChild(verifierKey, invoiceNumber)
  const signature = signingKey.sign(plaintext).toDER() as number[]
  const senderPublicKey = signerKey.toPublicKey().encode(true)
  const version = toArray(VERSION, 'hex')
  return version.concat(
    senderPublicKey,
    recipientAnyone ? [0] : verifierKey.encode(true),
    keyID,
    signature
  )
}

/**
 * Verifies a message using the BRC-77 message signing protocol.
 * @param message The message to verify.
 * @param sig The message signature to be verified.
 * @param [recipient] The private key of the message verifier. This can be omitted if the message is verifiable by anyone.
 *
 * @returns True if the message is verified.
 *
 * A valid signature authenticates the exact bytes and intended verifier, not
 * application purpose or freshness. Authorization messages must embed a domain,
 * audience, unique challenge, and expiry and must reject challenge reuse.
 */
export const verify = (message: number[], sig: number[], recipient?: PrivateKey): boolean => {
  const plaintext = copyMessageBytes(message, 'Message')
  const signatureBytes = copyMessageBytes(
    sig,
    'Signed message',
    MAX_SIGNED_MESSAGE_BYTES,
    MIN_SIGNED_MESSAGE_BYTES
  )
  const reader = new Reader(signatureBytes)
  const messageVersion = toHex(reader.read(4))
  if (messageVersion !== VERSION) {
    throw new Error(`Message version mismatch: Expected ${VERSION}, received ${messageVersion}`)
  }
  const signer = PublicKey.fromString(toHex(reader.read(33)))
  const [verifierFirst] = reader.read(1)
  let recipientKey: PrivateKey
  if (verifierFirst === 0) {
    recipientKey = new PrivateKey(1)
  } else {
    const verifierRest = reader.read(32)
    const verifierDER = toHex([verifierFirst, ...verifierRest])
    if (recipient === undefined) {
      throw new TypeError(
        `This signature can only be verified with knowledge of a specific private key. The associated public key is: ${verifierDER}`
      )
    }
    recipientKey = copyPrivateKey(recipient, 'Recipient')
    const recipientDER = recipientKey.toPublicKey().encode(true, 'hex') as string
    if (verifierDER !== recipientDER) {
      throw new Error(
        `The recipient public key is ${recipientDER} but the signature requres the recipient to have public key ${verifierDER}`
      )
    }
  }
  const keyID = toBase64(reader.read(32))
  const signatureDER = toHex(reader.read(reader.bin.length - reader.pos))
  const signature = Signature.fromDER(signatureDER, 'hex')
  const invoiceNumber = `2-message signing-${keyID}`
  const signingKey = signer.deriveChild(recipientKey, invoiceNumber)
  return signingKey.verify(plaintext, signature) === true
}
